{{(() => {
  // As the console's order box: the goods, then what Fulfilya keeps (2026-10-02).
  // Total = Amount; goods = total - delivery - fee, from the same two stored lines.
  const en = appsmith.store.bo_lang === 'en';
  const d = GetOrderDetails.data[0] || {};
  const num = (x) => { const v = Number(String(x ?? '').replace(',', '.').replace('$', '')); return isNaN(v) ? 0 : v; };
  const eur = (v) => v.toLocaleString('bg-BG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
  const delivery = num(d.delivery_fee), fee = num(d.cod_fee), total = num(d.amount);
  if (d.delivery_fee == null && d.cod_fee == null) return '-';
  if (d.payment_method !== 'COD') return (en ? 'Delivery ' : 'Доставка ') + eur(delivery);
  const goods = Math.max(0, total - delivery - fee);
  return (en ? 'COD amount (goods) ' : 'Стока (наложен платеж) ') + eur(goods) + ' · ' + (en ? 'delivery ' : 'доставка ') + eur(delivery) + ' · ' + (en ? 'COD fee ' : 'такса НП ') + eur(fee);
})()}}
